// Parse configuration into usable map
const config = $('Load Pricing Config').all();
const configMap = {};

config.forEach(row => {
  configMap[row.json.parameter_name] = parseFloat(row.json.value);
});

// Get properties from PriceLabs
const properties = $json.properties;
const results = [];

properties.forEach(prop => {
  // Calculate days until next booking
  const nextBooking = new Date(prop.next_booking_date);
  const today = new Date();
  const daysUntilBooking = Math.ceil((nextBooking - today) / (1000 * 60 * 60 * 24));

  // Get thresholds from config
  const occupancy = prop.occupancy_last_30_days;
  const lowOccupancyThreshold = configMap.low_occupancy_threshold || 60;
  const weekendAdjustmentDays = configMap.weekend_adjustment_days || 5;

  // Determine if action is needed
  let actionNeeded = false;
  let actionType = null;
  let reasoning = [];

  // Check occupancy
  if (occupancy < lowOccupancyThreshold) {
    actionNeeded = true;
    actionType = 'occupancy_discount';
    reasoning.push(`Occupancy at ${occupancy}% below threshold of ${lowOccupancyThreshold}%`);
  }

  // Check weekend vacancy
  const dayOfWeek = nextBooking.getDay();
  const isWeekend = dayOfWeek === 5 || dayOfWeek === 6 || dayOfWeek === 0;

  if (isWeekend && daysUntilBooking <= weekendAdjustmentDays && occupancy < 70) {
    actionNeeded = true;
    actionType = 'weekend_discount';
    reasoning.push(`Weekend in ${daysUntilBooking} days with ${occupancy}% occupancy`);
  }

  // Check last-minute
  if (daysUntilBooking <= 3 && occupancy < 50) {
    actionNeeded = true;
    actionType = 'last_minute_discount';
    reasoning.push('Critical: Last-minute vacancy');
  }

  results.push({
    json: {
      property_id: prop.id,
      property_name: prop.name,
      current_base_price: prop.base_price,
      occupancy: occupancy,
      days_until_booking: daysUntilBooking,
      action_needed: actionNeeded,
      action_type: actionType,
      reasoning: reasoning.join('; '),
      timestamp: new Date().toISOString(),
      config_used: configMap
    }
  });
});

return results;

const property = $input.first().json;
const config = property.config_used;

const occupancy = property.occupancy;
const currentPrice = property.current_base_price;

// Tiered discount logic
let discountPercentage = 0;

if (occupancy < 40) {
  discountPercentage = config.discount_percentage_tier3 || 20;
} else if (occupancy < 50) {
  discountPercentage = config.discount_percentage_tier2 || 15;
} else if (occupancy < 60) {
  discountPercentage = config.discount_percentage_tier1 || 10;
}

const newPrice = Math.round(currentPrice * (1 - discountPercentage / 100));
const requiresApproval = discountPercentage >= 15;

return {
  json: {
    ...property,
    discount_percentage: discountPercentage,
    new_base_price: newPrice,
    price_change_amount: currentPrice - newPrice,
    requires_manual_approval: requiresApproval,
    adjustment_reason: `Occupancy-based: ${occupancy}% occupancy, ${discountPercentage}% discount applied`
  }
};

const property = $input.first().json;
const currentPrice = property.current_base_price;
const weekendDiscount = 10;
const newWeekendPrice = Math.round(currentPrice * 0.9);

const nextBooking = new Date(property.timestamp);
nextBooking.setDate(nextBooking.getDate() + property.days_until_booking);
const dayOfWeek = nextBooking.getDay();

const weekendStart = new Date(nextBooking);
weekendStart.setDate(weekendStart.getDate() - (dayOfWeek === 0 ? 2 : dayOfWeek === 6 ? 1 : 0));

const weekendEnd = new Date(weekendStart);
weekendEnd.setDate(weekendEnd.getDate() + 2);

return {
  json: {
    ...property,
    action_type: 'weekend_discount',
    discount_percentage: weekendDiscount,
    new_weekend_price: newWeekendPrice,
    price_change_amount: currentPrice - newWeekendPrice,
    date_range_start: weekendStart.toISOString().split('T')[0],
    date_range_end: weekendEnd.toISOString().split('T')[0],
    requires_manual_approval: false,
    adjustment_reason: `Weekend vacancy ${property.days_until_booking} days out - 10% discount`
  }
};

const property = $input.first().json;
const currentPrice = property.current_base_price;
const emergencyDiscount = 25;
const newPrice = Math.round(currentPrice * 0.75);

return {
  json: {
    ...property,
    discount_percentage: emergencyDiscount,
    new_base_price: newPrice,
    price_change_amount: currentPrice - newPrice,
    requires_manual_approval: false,
    adjustment_reason: `EMERGENCY: Last-minute vacancy (${property.days_until_booking} days)`
  }
};

